def transform(grid):
    # A transcription may have a short row; restore rectangular dimensions.
    h = len(grid)
    w = max(map(len, grid))
    out = [row[:] + [0] * (w - len(row)) for row in grid]

    # Within each wallpaper row the colors repeat horizontally. Fit each
    # row's shortest supported period, ignoring zeros, then fill the mask.
    for r in range(h):
        if r < 2:
            for c in range(w):
                if out[r][c] == 0:
                    out[r][c] = 1
            continue
        if r == 2:
            for c in range(w):
                if out[r][c] == 0:
                    out[r][c] = 1 if c < 2 else 4
            continue

        # Zeroed sections can include the framing margin.
        for c in range(min(2, w)):
            if out[r][c] == 0:
                out[r][c] = 1
        if w > 2 and out[r][2] == 0:
            out[r][2] = 4

        # Only infer wallpaper colors at columns 3 onward. Select the
        # smallest period with the strongest agreement across observed cells.
        observed = [(c, out[r][c]) for c in range(3, w) if out[r][c] != 0]
        if not observed:
            continue
        scores = {}
        maps = {}
        for period in range(2, min(12, w - 2)):
            buckets = {}
            for c, value in observed:
                counts = buckets.setdefault(c % period, Counter())
                counts[value] += 1
            scores[period] = sum(max(counts.values()) for counts in buckets.values())
            maps[period] = {residue: counts.most_common(1)[0][0]
                            for residue, counts in buckets.items()}
        best_score = max(scores.values())
        # Equal fit: prefer the shorter period (the primitive cycle).
        period = min(p for p, score in scores.items() if score == best_score)
        color = maps[period]
        for c in range(3, w):
            if out[r][c] == 0:
                out[r][c] = color[c % period]
    return out
